CREATE OR ALTER TRIGGER [dbo].[ResponsibilityTypeRelation_AfterUpdate] ON [dbo].[ResponsibilityTypeRelation] AFTER UPDATE AS BEGIN SET NOCOUNT ON;
IF( UPDATE(PermissionsBitMask)) BEGIN INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT DISTINCT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN deleted D ON I.ResponsibilityTypeID = D.ResponsibilityTypeID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] rtrr ON (rtrr.ResponsibilityTypeID = I.ResponsibilityTypeID AND rtrr.[Object] = I.[ObjectType] AND rtrr.ObjectID = I.ObjectID) INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on RA.RuleID = rtrr.ID INNER JOIN [dbo].[Asset] A ON RA.AssetID = A.ID WHERE (I.PermissionsBitMask ^ D.PermissionsBitMask) & 1 = 1 AND RA.AssetTypeID = 0;
INSERT INTO [queue].[Task] ([Action], [Custom], [Object], [ObjectID],[AssetID]) SELECT DISTINCT 'ObjectIndex', 'U', A.Object, A.ObjectID, A.ID FROM inserted I INNER JOIN deleted D ON I.ResponsibilityTypeID = D.ResponsibilityTypeID INNER JOIN [dbo].[ResponsibilityTypeRelationRule] rtrr ON (rtrr.ResponsibilityTypeID = I.ResponsibilityTypeID AND rtrr.[Object] = I.[ObjectType] AND rtrr.ObjectID = I.ObjectID) INNER JOIN [dbo].[ResponsibilityRuleResultAsset] RA on RA.RuleID = rtrr.ID INNER JOIN [dbo].[Asset] A ON RA.AssetTypeID = A.AssetTypeID WHERE (I.PermissionsBitMask ^ D.PermissionsBitMask) & 1 = 1 AND RA.AssetID = 0;
END; END
